import math
for _ in range(int(input())):
	(k, n) = map(int, input().split())
	k1 = k
	summ = n * (n + 1) // 2
	if n > 44720 or summ > k:
		print(-1)
	else:
		fact = []
		for i in range(1, int(math.sqrt(k)) + 1):
			if k % i == 0:
				fact += [i, k // i]
		fact.sort()
		for i in fact:
			if i >= summ:
				print(k // i)
				break
